@@ -0,0 +1,139 @@
+import { beforeEach, describe, expect, it, vi } from "vitest";
+
+const { updateConfigMock } = vi.hoisted(() => ({ updateConfigMock: vi.fn() }));
+vi.mock("openclaw/plugin-sdk/config-mutation", () => ({
+  updateConfig: updateConfigMock,
+}));
+
+const sendMessageMock = vi.fn().mockResolvedValue(undefined);
+
+import { handleVcardCommand } from "./vcard-command-handler.js";
+
+const SELF_JID = "15550009999@s.whatsapp.net";
+const OTHER_JID = "15550001111@s.whatsapp.net";
+const SAMPLE_VCARD = "BEGIN:VCARD\nVERSION:3.0\nFN:John\nTEL:+5511999988888\nEND:VCARD";
+
+function makeParams(
+  overrides: Partial<{
+    fromMe: boolean;
+    selfChatMode: boolean;
+    configWrites: boolean;
+    command: string;
+    quotedVcard: string | undefined;
+    selfJid: string;
+    remoteJid: string;
+    accountId: string;
+  }> = {},
+) {
+  return {
+    fromMe: overrides.fromMe ?? true,
+    selfChatMode: overrides.selfChatMode ?? true,
+    configWrites: overrides.configWrites ?? true,
+    command: overrides.command ?? "add",
+    quotedVcard: "quotedVcard" in overrides ? overrides.quotedVcard : SAMPLE_VCARD,
+    selfJid: overrides.selfJid ?? SELF_JID,
+    remoteJid: overrides.remoteJid ?? SELF_JID,
+    accountId: overrides.accountId ?? "default",
+    sendMessage: sendMessageMock,
+  };
+}
+
+function mockConfig(manualFrom: string[] = []) {
+  updateConfigMock.mockImplementation(async (mutator: (cfg: unknown) => unknown) =>
+    mutator({ channels: { whatsapp: { dmPolicy: "open-except", manualFrom } } }),
+  );
+}
+
+beforeEach(() => {
+  vi.clearAllMocks();
+  mockConfig([]);
+});
+
+describe("handleVcardCommand", () => {
+  it("returns null when selfChatMode is false", async () => {
+    const result = await handleVcardCommand(makeParams({ selfChatMode: false }));
+    expect(result).toBeNull();
+    expect(updateConfigMock).not.toHaveBeenCalled();
+  });
+
+  it("returns null when configWrites is false", async () => {
+    const result = await handleVcardCommand(makeParams({ configWrites: false }));
+    expect(result).toBeNull();
+    expect(updateConfigMock).not.toHaveBeenCalled();
+  });
+
+  it("returns null when not fromMe", async () => {
+    const result = await handleVcardCommand(makeParams({ fromMe: false }));
+    expect(result).toBeNull();
+  });
+
+  it("returns null when remoteJid is not selfJid", async () => {
+    const result = await handleVcardCommand(makeParams({ remoteJid: OTHER_JID }));
+    expect(result).toBeNull();
+  });
+
+  it("returns null when quotedVcard is absent", async () => {
+    const result = await handleVcardCommand(makeParams({ quotedVcard: undefined }));
+    expect(result).toBeNull();
+  });
+
+  it("returns null for unrecognized command", async () => {
+    const result = await handleVcardCommand(makeParams({ command: "delete" }));
+    expect(result).toBeNull();
+  });
+
+  it("returns null when vcard has no phone", async () => {
+    const result = await handleVcardCommand({
+      ...makeParams(),
+      quotedVcard: "BEGIN:VCARD\nVERSION:3.0\nFN:John\nEND:VCARD",
+    });
+    expect(result).toBeNull();
+  });
+
+  it("add: adds phone and replies confirmation", async () => {
+    mockConfig([]);
+    const result = await handleVcardCommand(makeParams({ command: "add" }));
+    expect(result).toBe("added");
+    expect(updateConfigMock).toHaveBeenCalledOnce();
+    expect(sendMessageMock).toHaveBeenCalledWith(SELF_JID, {
+      text: "Added +5511999988888 to manual list",
+    });
+  });
+
+  it("add: replies already-in-list when phone is present", async () => {
+    mockConfig(["+5511999988888"]);
+    const result = await handleVcardCommand(makeParams({ command: "add" }));
+    expect(result).toBe("already");
+    expect(updateConfigMock).toHaveBeenCalledTimes(1); // read-only pass
+    expect(sendMessageMock).toHaveBeenCalledWith(SELF_JID, { text: "Already in manual list" });
+  });
+
+  it("rm: removes phone and replies confirmation", async () => {
+    mockConfig(["+5511999988888"]);
+    const result = await handleVcardCommand(makeParams({ command: "rm" }));
+    expect(result).toBe("removed");
+    expect(updateConfigMock).toHaveBeenCalledTimes(1); // single atomic read+write pass
+    expect(sendMessageMock).toHaveBeenCalledWith(SELF_JID, {
+      text: "Removed +5511999988888 from manual list",
+    });
+  });
+
+  it("rm: replies not-in-list when phone is absent", async () => {
+    mockConfig([]);
+    const result = await handleVcardCommand(makeParams({ command: "rm" }));
+    expect(result).toBe("not-found");
+    expect(updateConfigMock).toHaveBeenCalledTimes(1); // read-only pass
+    expect(sendMessageMock).toHaveBeenCalledWith(SELF_JID, { text: "Not in manual list" });
+  });
+
+  it("command matching is case-insensitive", async () => {
+    const result = await handleVcardCommand(makeParams({ command: "ADD" }));
+    expect(result).toBe("added");
+  });
+
+  it("command matching trims whitespace", async () => {
+    const result = await handleVcardCommand(makeParams({ command: "  rm  " }));
+    // no phone in list, so not-found
+    expect(result).toBe("not-found");
+  });
+});
diff --git a/extensions/whatsapp/src/inbound/vcard-command-handler.ts b/extensions/whatsapp/src/inbound/vcard-command-handler.ts
new file mode 100644
index 0000000000000..315322debaaee
--- /dev/null
+++ b/extensions/whatsapp/src/inbound/vcard-command-handler.ts
@@ -0,0 +1,112 @@
+import type { OpenClawConfig } from "openclaw/plugin-sdk/config-contracts";
+import { updateConfig } from "openclaw/plugin-sdk/config-mutation";
+import { normalizeE164 } from "../text-runtime.js";
+import { parseVcard } from "../vcard.js";
+
+export type VcardCommandResult = "added" | "removed" | "already" | "not-found" | null;
+
+export type VcardCommandParams = {
+  fromMe: boolean;
+  selfChatMode: boolean;
+  configWrites: boolean;
+  command: string;
+  quotedVcard: string | undefined;
+  selfJid: string;
+  remoteJid: string;
+  accountId: string;
+  sendMessage: (jid: string, content: { text: string }) => Promise<unknown>;
+};
+
+function readManualFrom(cfg: OpenClawConfig, accountId: string): string[] {
+  const raw = cfg as unknown as { channels?: { whatsapp?: Record<string, unknown> } };
+  const whatsapp = raw.channels?.whatsapp;
+  if (!whatsapp) return [];
+  if (accountId !== "default") {
+    const accounts = whatsapp.accounts as Record<string, unknown> | undefined;
+    const acct = accounts?.[accountId] as Record<string, unknown> | undefined;
+    if (Array.isArray(acct?.manualFrom)) return acct.manualFrom as string[];
+  }
+  return Array.isArray(whatsapp.manualFrom) ? (whatsapp.manualFrom as string[]) : [];
+}
+
+function writeManualFrom(cfg: OpenClawConfig, accountId: string, next: string[]): OpenClawConfig {
+  const raw = cfg as unknown as Record<string, unknown>;
+  const channels = (raw.channels ?? {}) as Record<string, unknown>;
+  const whatsapp = (channels.whatsapp ?? {}) as Record<string, unknown>;
+  if (accountId !== "default") {
+    const accounts = (whatsapp.accounts ?? {}) as Record<string, unknown>;
+    const acct = (accounts[accountId] ?? {}) as Record<string, unknown>;
+    return {
+      ...raw,
+      channels: {
+        ...channels,
+        whatsapp: {
+          ...whatsapp,
+          accounts: { ...accounts, [accountId]: { ...acct, manualFrom: next } },
+        },
+      },
+    } as OpenClawConfig;
+  }
+  return {
+    ...raw,
+    channels: { ...channels, whatsapp: { ...whatsapp, manualFrom: next } },
+  } as OpenClawConfig;
+}
+
+export async function handleVcardCommand(params: VcardCommandParams): Promise<VcardCommandResult> {
+  if (!params.selfChatMode || !params.configWrites) return null;
+  if (!params.fromMe) return null;
+  if (params.remoteJid !== params.selfJid) return null;
+  if (!params.quotedVcard) return null;
+
+  const cmd = params.command.trim().toLowerCase();
+  if (cmd !== "add" && cmd !== "rm") return null;
+
+  const parsed = parseVcard(params.quotedVcard);
+  if (parsed.phones.length === 0) return null;
+
+  const phone = normalizeE164(parsed.phones[0]);
+
+  if (cmd === "add") {
+    let outcome: "added" | "already" = "already";
+    await updateConfig((cfg) => {
+      const list = readManualFrom(cfg, params.accountId);
+      const isPresent = list.map(normalizeE164).some((e) => e === phone);
+      if (isPresent) {
+        outcome = "already";
+        return cfg;
+      }
+      outcome = "added";
+      return writeManualFrom(cfg, params.accountId, [...list, phone]);
+    });
+    if (outcome === "already") {
+      await params.sendMessage(params.selfJid, { text: "Already in manual list" });
+      return "already";
+    }
+    await params.sendMessage(params.selfJid, { text: `Added ${phone} to manual list` });
+    return "added";
+  }
+
+  // cmd === "rm": single atomic mutator — read and write in one call.
+  let outcome: "removed" | "not-found" = "not-found";
+  await updateConfig((cfg) => {
+    const list = readManualFrom(cfg, params.accountId);
+    const idx = list.map(normalizeE164).findIndex((e) => e === phone);
+    if (idx === -1) {
+      outcome = "not-found";
+      return cfg;
+    }
+    outcome = "removed";
+    return writeManualFrom(
+      cfg,
+      params.accountId,
+      list.filter((_, i) => i !== idx),
+    );
+  });
+  if (outcome === "not-found") {
+    await params.sendMessage(params.selfJid, { text: "Not in manual list" });
+    return "not-found";
+  }
+  await params.sendMessage(params.selfJid, { text: `Removed ${phone} from manual list` });
+  return "removed";
+}
